flow.set('zelnumRealtimeQuote',undefined);
 const apiKey=env.get('ZELNUM_API_KEY');
 const series=String(env.get('ZELNUM_SERIES')||'phone').trim().toLowerCase();
 const identifier=String(env.get('ZELNUM_IDENTIFIER')||'').trim();
 const productId=Number(env.get('ZELNUM_REALTIME_PRODUCT_ID'));
 if(!apiKey||!identifier||!Number.isInteger(productId)||productId<=0||!['phone','email'].includes(series)){node.error('Set API key, identifier, current realtime product ID and phone/email series. Register at https://app.zelnum.com',msg);return null;}
 const body={identifier,product_ids:[productId]};
 if(series==='phone')body.country=String(env.get('ZELNUM_COUNTRY')||'US').trim().toUpperCase();
 msg.method='POST';msg.url=`https://api.zelnum.com/api/v1/realtime/quote/${series}`;
 msg.headers={'X-API-Key':apiKey,'Content-Type':'application/json'};
 msg.payload=body;msg.zelnum={series,body:JSON.parse(JSON.stringify(body))};
 return msg;

delete msg.headers;
if (Number(msg.statusCode) < 200 || Number(msg.statusCode) >= 300 || !msg.payload || !msg.payload.quote || !msg.zelnum) {
  flow.set('zelnumRealtimeQuote', undefined); node.error('Quote failed: ' + ((msg.payload && (msg.payload.message || msg.payload.code)) || msg.statusCode), msg); return null;
}
const quote = msg.payload.quote;
if (!quote.quote_token || !Number.isFinite(Number(quote.total)) || !Number.isFinite(Date.parse(quote.expires_at)) || Date.parse(quote.expires_at) <= Date.now()) {
  flow.set('zelnumRealtimeQuote', undefined); node.error('Invalid or expired quote; request a new one.', msg); return null;
}
flow.set('zelnumRealtimeQuote', {quote, request: msg.zelnum});
msg.payload = {quote, count: 1, next: 'Review the price before clicking the separate BILLABLE inject. Keep the idempotency key for retries; use a new key for each new request.'};
return msg;

const saved = flow.get('zelnumRealtimeQuote');
const apiKey = env.get('ZELNUM_API_KEY');
const idempotencyKey = String(env.get('ZELNUM_IDEMPOTENCY_KEY') || '').trim();
if (!apiKey || !idempotencyKey) { node.error('Set API key and a unique idempotency key for this logical request.', msg); return null; }
if (!saved || !saved.request || !saved.quote || Date.parse(saved.quote.expires_at) <= Date.now()) { node.error('Get a fresh quote first; quotes expire.', msg); return null; }
const series = String(env.get('ZELNUM_SERIES') || 'phone').trim().toLowerCase();
const current = {identifier: String(env.get('ZELNUM_IDENTIFIER') || '').trim(), product_ids: [Number(env.get('ZELNUM_REALTIME_PRODUCT_ID'))]};
if (series === 'phone') current.country = String(env.get('ZELNUM_COUNTRY') || 'US').trim().toUpperCase();
if (series !== saved.request.series || JSON.stringify(current) !== JSON.stringify(saved.request.body)) { node.error('Inputs changed after quoting (including country). Get a new quote and review its price.', msg); return null; }
if (saved.idempotencyKey && saved.idempotencyKey !== idempotencyKey) { node.error('This quote has already been executed. Keep its key for retries or get a new quote for a new request.', msg); return null; }
saved.idempotencyKey = idempotencyKey; flow.set('zelnumRealtimeQuote', saved);
msg.method = 'POST'; msg.url = `https://api.zelnum.com/api/v1/realtime/check/${series}`;
msg.headers = {'X-API-Key': apiKey, 'Content-Type': 'application/json', 'Idempotency-Key': idempotencyKey, 'X-ZelNum-Quote': saved.quote.quote_token, 'X-ZelNum-Quote-Amount': String(saved.quote.total)};
msg.payload = JSON.parse(JSON.stringify(saved.request.body));
return msg;
